        b = gzip.decompress(b)
    return b.decode('utf-8-sig').replace('\r\n', '\n').replace('\r', '\n')


def lines(path):
    return [l for l in read_text(path).split('\n') if l.strip() != '']


def local_to_utc(naive, tz, fold=0):
    return naive.replace(tzinfo=tz, fold=fold).astimezone(UTC)


def std_offset(tz):
    # standard offset of a zone: smaller utcoffset over a year
    best = None
    for m in (1, 7):
        o = datetime(2026, m, 1, tzinfo=tz).utcoffset()
        best = o if best is None or o < best else best
    return best


