    out = []
    hdr = None
    for row in csv.reader(io.StringIO(text)):
        if not row or all(not c.strip() for c in row):
            continue
        if 'Badge' in row and 'Punch' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]].strip()
        d = datetime.strptime(g('Date'), '%m/%d/%Y')
        t = g('Time').upper()
        if t.endswith('AM') or t.endswith('PM'):
            ap = t[-2:]
            hh, mm, ss = [int(x) for x in t[:-2].strip().split(':')]
            hh = hh % 12 + (12 if ap == 'PM' else 0)
        else:
            hh, mm, ss = [int(x) for x in t.split(':')]
        zone = g('Zone').upper()
        fold = 1 if zone.endswith('ST') else 0
        inst = local_to_utc(d.replace(hour=hh, minute=mm, second=ss), tz, fold)
        out.append((g('Record'), g('Badge'), g('Punch').upper(), inst))
    return out


def parse_epoch(text):
    out = []
    schema = 1
    for l in text.split('\n'):
        if not l.strip():
            continue
        o = json.loads(l)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, dr = o['punch_id'], o['employee'], o['direction']
            ts = int(o['epoch_ms']) // 1000
        else:
            pid, emp, dr = o['id'], o['emp'], o['dir']
            ts = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
        out.append((str(pid), emp, dr.upper(), datetime.fromtimestamp(ts, UTC)))
    return out


def parse_offset(text):
    out = []
    for r in csv.DictReader(io.StringIO(text), delimiter=';'):
        dr = 'IN' if r['event'].strip() == 'clock_in' else 'OUT'
        inst = datetime.fromisoformat(r['timestamp'].strip()).astimezone(UTC)
        out.append((r['punch_id'], r['employee'], dr, inst))
    return out


def parse_legacy(text, tz, emp_ids):
    out = []
    default = std_offset(tz)
    off = default
    for l in text.split('\n'):
        if not l.strip():
            continue
        t = l[0]
        if t == 'H':
            s = l[13:18].strip()
            if len(s) == 5 and s[0] in '+-':
                v = timedelta(hours=int(s[1:3]), minutes=int(s[3:5]))
                off = v if s[0] == '+' else -v
            else:
                off = default
        elif t == 'D':
            pid = l[1:9]
            bn = l[9:15].strip()
            emp = 'E' + bn
            if emp not in emp_ids and bn.isdigit():
                emp = 'E' + bn.zfill(4)
            dr = 'IN' if l[15] == 'I' else 'OUT'
            naive = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            out.append((pid, emp, dr, (naive - off).replace(tzinfo=UTC)))
    return out


def parse_de(text, tz):
    out = []
    rd = csv.reader(io.StringIO(text), delimiter='\t')
    hdr = None
    for row in rd:
        if not row or all(not c.strip() for c in row):
            continue
        if 'Ausweis' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        g = lambda n: row[hdr[n]].strip()
        d = datetime.strptime(g('Datum') + ' ' + g('Uhrzeit'), '%d.%m.%Y %H:%M')
        fold = 1 if g('Zeitzone').upper() == 'MEZ' else 0
        out.append((g('Nr'), g('Ausweis'), 'IN' if g('Buchung') == 'K' else 'OUT',
                    local_to_utc(d, tz, fold)))
    return out


def parse_local_csv(text, tz):
    out = []
    for r in csv.DictReader(io.StringIO(text)):
        d = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'].strip(), r['employee_id'].strip(), r['direction'].strip().upper(),
                    local_to_utc(d, tz, 0)))
    return out


def parse_local_jsonl(text, tz):
    out = []
    for l in text.split('\n'):
        if not l.strip():
            continue
        p = json.loads(l)['punch']
        d = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], p['type'].upper(), local_to_utc(d, tz, 0)))
    return out


def round_inst(inst, tz):
    off = inst.astimezone(tz).utcoffset()
    loc = inst + off
    sec = loc.minute * 60 + loc.second
    r = (sec + 180) // 360 * 360
    return inst + timedelta(seconds=r - sec)


def night_minutes(a, b, tz):
    la = a.astimezone(tz).date() - timedelta(days=1)
    lb = b.astimezone(tz).date() + timedelta(days=1)
    total = 0
    d = la
    while d <= lb:
        s = local_to_utc(datetime.combine(d, dtime(22, 0)), tz)
        e = local_to_utc(datetime.combine(d + timedelta(days=1), dtime(6, 0)), tz)
        lo, hi = max(a, s), min(b, e)
        if hi > lo:
            total += int((hi - lo).total_seconds())
        d += timedelta(days=1)
    return total // 60


def main(indir, outfile):
    period = json.load(open(os.path.join(indir, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00'))

    def rcsv(name):
        return list(csv.DictReader(io.StringIO(read_text(os.path.join(indir, name)))))

    sites = {r['site'].strip(): (ZoneInfo(r['timezone'].strip()), r['format'].strip()) for r in rcsv('sites.csv')}
    employees = [(r['employee_id'].strip(), r['home_site'].strip()) for r in rcsv('employees.csv')]
    emp_ids = {e for e, _ in employees}
    home = {e: sites[h][0] for e, h in employees}
    rates = defaultdict(list)
    for r in rcsv('rates.csv'):
        rates[r['employee_id'].strip()].append((date.fromisoformat(r['effective_from'].strip()),
                                                Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}   # (site,id) -> [emp, dir, inst]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(indir, 'exports', site)
        if not os.path.isdir(d):
            continue
        for path in sorted(glob.glob(os.path.join(d, '*'))):
            if not os.path.isfile(path):
                continue
            text = read_text(path)
            if fmt == 'abbr-csv':
                rows = parse_abbr(text, tz)
            elif fmt == 'epoch-jsonl':
                rows = parse_epoch(text)
            elif fmt == 'offset-csv':
                rows = parse_offset(text)
            elif fmt == 'legacy-fixed':
                rows = parse_legacy(text, tz, emp_ids)
            elif fmt == 'de-tsv':
                rows = parse_de(text, tz)
            elif fmt == 'local-csv':
                rows = parse_local_csv(text, tz)
            elif fmt == 'local-jsonl':
                rows = parse_local_jsonl(text, tz)
            else:
                raise SystemExit('unknown format ' + fmt)
            for pid, emp, dr, inst in rows:
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp, dr, inst]

