    for path in sorted(glob.glob(os.path.join(indir, 'corrections', '*'))):
        if os.path.isfile(path):
            for r in csv.DictReader(io.StringIO(read_text(path))):
                r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                r['_t'] = datetime.fromisoformat(r['issued_at'].replace('Z', '+00:00'))
                corr.append(r)
    corr = [c for c in corr if c['_t'] <= cutoff]
    corr.sort(key=lambda c: (c['_t'], c['correction_id']))
    applied = 0
    for c in corr:
        k = (c['site'], c['punch_id'])
        act = c['action']
        if act == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif act == 'set':
            if k in punches:
                punches[k][2] = datetime.fromisoformat(c['time']).astimezone(UTC)
                applied += 1
        elif act == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'], c['type'].upper(), datetime.fromisoformat(c['time']).astimezone(UTC)]
                applied += 1

    byemp = defaultdict(list)
    for (site, pid), (emp, dr, inst) in punches.items():
        if emp in emp_ids:
            byemp[emp].append((inst, 0 if dr == 'OUT' else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
           for e, _ in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def workday(e, r):
        return r.astimezone(home[e]).date()

    def inper(dd):
        return pstart <= dd <= pend

