                punches[k] = [c['employee'], c['type'].upper(), datetime.fromisoformat(c['time']).astimezone(UTC)]
                applied += 1

    byemp = defaultdict(list)
    for (site, pid), (emp, dr, inst) in punches.items():
        if emp in emp_ids:
            byemp[emp].append((inst, 0 if dr == 'OUT' else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
           for e, _ in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def workday(e, r):
        return r.astimezone(home[e]).date()

    def inper(dd):
        return pstart <= dd <= pend

    for e, _ in employees:
        ps = sorted(byemp.get(e, []), key=lambda p: p[:4])
        kept = []
        last = None
        for inst, _o, site, pid, dr in ps:
            r = round_inst(inst, sites[site][0])
            if last is not None and last[4] == dr and (inst - last[0]).total_seconds() <= 300:
                if inper(workday(e, r)):
                    exc['duplicates_dropped'] += 1
                continue
            p = (inst, _o, site, pid, dr, r)
            kept.append(p)
            last = p
        shifts = []
        cur = None
        def open_(p):
            if inper(workday(e, p[5])):
                exc['open_shifts'] += 1
        for p in kept:
            if p[4] == 'IN':
                if cur:
                    open_(cur)
                cur = p
            else:
                if cur:
                    if p[5] - cur[5] <= timedelta(hours=16):
                        shifts.append((cur, p))
                    else:
                        open_(cur)
                        if inper(workday(e, p[5])):
                            exc['orphan_outs'] += 1
                    cur = None
                elif inper(workday(e, p[5])):
                    exc['orphan_outs'] += 1
        if cur:
            open_(cur)
        # shifts in period
        sl = []
        for i, o in shifts:
            wd = workday(e, i[5])
            if not inper(wd):
                continue
            tz = sites[i[2]][0]
            worked = max(0, int((o[5] - i[5]).total_seconds()) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i[5], o[5], tz), paid)
            sl.append(dict(inst=i[5], wd=wd, paid=paid, night=night))
        sl.sort(key=lambda s: s['inst'])
        daily = defaultdict(int)
        for s in sl:
            before = daily[s['wd']]
            daily[s['wd']] += s['paid']
            s['dot'] = max(0, before + s['paid'] - max(480, before)) if before + s['paid'] > 480 else 0
        week = defaultdict(int)
        for s in sl:
            reg = s['paid'] - s['dot']
            wk = s['wd'] - timedelta(days=s['wd'].weekday())
            before = week[wk]
            week[wk] += reg
            s['wot'] = max(0, before + reg - max(2400, before)) if before + reg > 2400 else 0
        gross = Decimal(0)
        R = res[e]
        for s in sl:
            ot = s['dot'] + s['wot']
            regm = s['paid'] - ot
            rate = None
            for ef, rt in rates.get(e, []):
                if ef <= s['wd']:
                    rate = rt
            if rate is None and rates.get(e):
                rate = rates[e][0][1]
            rate = rate or Decimal(0)
            gross += rate * (Decimal(regm) + Decimal('1.5') * ot) / 60 + rate * Decimal('0.15') * s['night'] / 60
            R['shifts'] += 1
            R['paid_minutes'] += s['paid']
            R['overtime_minutes'] += ot
            R['night_minutes'] += s['night']
        R['gross'] = gross.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
    for R in res.values():
        for k in tot:
            tot[k] += R[k]
    fmt = lambda R: {k: (format(v, '.2f') if k == 'gross' else v) for k, v in R.items()}
    out = dict(period=dict(start=period['start'], end=period['end']),
               employees={e: fmt(R) for e, R in res.items()}, exceptions=exc, totals=fmt(tot))
    with open(outfile, 'w') as f:
        json.dump(out, f, indent=1)


